class TestVectorProperties:
    """Validate mathematical properties of embedding vectors."""

    def test_embeddings_are_finite(
        self, index_data: Dict[str, List[float]]
    ):
        """No NaN or Inf values should exist in embeddings."""
        for doc_id, embedding in index_data.items():
            for i, val in enumerate(embedding):
                assert math.isfinite(val), (
                    f"Non-finite value {val} at index {i} for '{doc_id}'"
                )

    def test_embedding_norms_are_reasonable(
        self, index_data: Dict[str, List[float]]
    ):
        """L2 norms should be within expected range (typically 0.5-2.0 for normalized embeddings)."""
        for doc_id, embedding in index_data.items():
            norm = math.sqrt(sum(v * v for v in embedding))
            assert norm > 0.0, (
                f"Zero-norm embedding for '{doc_id}'"
            )
            assert norm < 100.0, (
                f"Extremely large norm {norm:.4f} for '{doc_id}'"
            )

    def test_embedding_mean_near_zero(
        self, index_data: Dict[str, List[float]]
    ):
        """Mean of embedding values should be near zero (common in trained models)."""
        for doc_id, embedding in index_data.items():
            mean = sum(embedding) / len(embedding)
            assert abs(mean) < 1.0, (
                f"Mean {mean:.6f} for '{doc_id}' is far from zero"
            )

    def test_embedding_std_dev_reasonable(
        self, index_data: Dict[str, List[float]]
    ):
        """Standard deviation should be within typical range (0.01-0.5)."""
        for doc_id, embedding in index_data.items():
            mean = sum(embedding) / len(embedding)
            variance = sum((v - mean) ** 2 for v in embedding) / len(embedding)
            std_dev = math.sqrt(variance)
            assert 0.001 <= std_dev <= 2.0, (
                f"Std dev {std_dev:.6f} for '{doc_id}' is outside expected range"
            )


