class TestSimilarityOperations:
    """Validate cosine similarity and nearest neighbor search."""

    @staticmethod
    def cosine_similarity(vec_a: List[float], vec_b: List[float]) -> float:
        """Compute cosine similarity between two vectors."""
        dot = sum(a * b for a, b in zip(vec_a, vec_b))
        norm_a = math.sqrt(sum(a * a for a in vec_a))
        norm_b = math.sqrt(sum(b * b for b in vec_b))
        if norm_a == 0.0 or norm_b == 0.0:
            return 0.0
        return dot / (norm_a * norm_b)

    def test_self_similarity_is_one(
        self, index_data: Dict[str, List[float]]
    ):
        """Cosine similarity of a vector with itself must be 1.0."""
        for doc_id, embedding in index_data.items():
            sim = self.cosine_similarity(embedding, embedding)
            assert abs(sim - 1.0) < 1e-6, (
                f"Self-similarity for '{doc_id}' is {sim:.10f}, expected 1.0"
            )

    def test_similarity_is_symmetric(
        self, index_data: Dict[str, List[float]]
    ):
        """Cosine similarity must be symmetric: sim(a,b) == sim(b,a)."""
        doc_ids = list(index_data.keys())
        if len(doc_ids) < 2:
            pytest.skip("Need at least 2 documents for symmetry test")
        for i in range(min(10, len(doc_ids))):
            for j in range(i + 1, min(10, len(doc_ids))):
                a = index_data[doc_ids[i]]
                b = index_data[doc_ids[j]]
                sim_ab = self.cosine_similarity(a, b)
                sim_ba = self.cosine_similarity(b, a)
                assert abs(sim_ab - sim_ba) < 1e-10, (
                    f"Similarity not symmetric for '{doc_ids[i]}' and '{doc_ids[j]}': "
                    f"{sim_ab:.10f} vs {sim_ba:.10f}"
                )

    def test_similarity_range(
        self, index_data: Dict[str, List[float]]
    ):
        """Cosine similarity must be in [-1.0, 1.0]."""
        doc_ids = list(index_data.keys())
        if len(doc_ids) < 2:
            pytest.skip("Need at least 2 documents for range test")
        for i in range(min(20, len(doc_ids))):
            for j in range(i + 1, min(20, len(doc_ids))):
                a = index_data[doc_ids[i]]
                b = index_data[doc_ids[j]]
                sim = self.cosine_similarity(a, b)
                assert -1.0 <= sim <= 1.0, (
                    f"Similarity {sim:.10f} outside [-1, 1] for "
                    f"'{doc_ids[i]}' and '{doc_ids[j]}'"
                )

    def test_nearest_neighbor_is_self(
        self, index_data: Dict[str, List[float]]
    ):
        """For each document, the nearest neighbor should be itself."""
        doc_ids = list(index_data.keys())
        if len(doc_ids) < 2:
            pytest.skip("Need at least 2 documents for NN test")
        for doc_id, embedding in index_data.items():
            best_sim = -float("inf")
            best_id = None
            for other_id, other_emb in index_data.items():
                sim = self.cosine_similarity(embedding, other_emb)
                if sim > best_sim:
                    best_sim = sim
                    best_id = other_id
            assert best_id == doc_id, (
                f"Nearest neighbor of '{doc_id}' is '{best_id}' "
                f"(sim={best_sim:.6f}), expected self"
            )


