class TestIndexQueries:
    """Test querying the index with synthetic embeddings."""

    @staticmethod
    def cosine_similarity(vec_a: List[float], vec_b: List[float]) -> float:
        dot = sum(a * b for a, b in zip(vec_a, vec_b))
        norm_a = math.sqrt(sum(a * a for a in vec_a))
        norm_b = math.sqrt(sum(b * b for b in vec_b))
        if norm_a == 0.0 or norm_b == 0.0:
            return 0.0
        return dot / (norm_a * norm_b)

    def test_query_returns_top_k(
        self, index_data: Dict[str, List[float]], embedding_dimension: int
    ):
        """Query with a synthetic vector should return top-k results."""
        if len(index_data) < 3:
            pytest.skip("Need at least 3 documents for query test")
        # Create a query vector that is the average of all embeddings
        query = [0.0] * embedding_dimension
        for emb in index_data.values():
            for i, v in enumerate(emb):
                query[i] += v
        query = [v / len(index_data) for v in query]

        # Compute similarities
        similarities = []
        for doc_id, emb in index_data.items():
            sim = self.cosine_similarity(query, emb)
            similarities.append((doc_id, sim))
        similarities.sort(key=lambda x: x[1], reverse=True)

        # Check top-3 results
        top_k = 3
        top_results = similarities[:top_k]
        assert len(top_results) == top_k, (
            f"Expected {top_k} results, got {len(top_results)}"
        )
        # Verify descending order
        for i in range(len(top_results) - 1):
            assert top_results[i][1] >= top_results[i + 1][1], (
                f"Results not in descending order at index {i}"
            )

    def test_query_with_known_document(
        self, index_data: Dict[str, List[float]]
    ):
        """Querying with a document's own embedding should return that document first."""
        if len(index_data) < 2:
            pytest.skip("Need at least 2 documents for this test")
        doc_ids = list(index_data.keys())
        # Pick a random document
        import random
        random.seed(42)
        target_id = random.choice(doc_ids)
        query = index_data[target_id]

        # Find top match
        best_sim = -float("inf")
        best_id = None
        for doc_id, emb in index_data.items():
            sim = self.cosine_similarity(query, emb)
            if sim > best_sim:
                best_sim = sim
                best_id = doc_id

        assert best_id == target_id, (
            f"Query with '{target_id}' embedding returned '{best_id}' as top match"
        )


