class TestPropertyBased:
    """Mathematical invariants verified via property-based testing."""

    @given(
        floats(min_value=-10.0, max_value=10.0, allow_nan=False, allow_infinity=False),
        floats(min_value=-10.0, max_value=10.0, allow_nan=False, allow_infinity=False),
        floats(min_value=-10.0, max_value=10.0, allow_nan=False, allow_infinity=False),
    )
    def test_cosine_similarity_bounds(self, x: float, y: float, z: float):
        """Cosine similarity of any two vectors must be in [-1, 1]."""
        vec_a = [x, y, z]
        vec_b = [z, x, y]  # permuted to avoid identical vectors
        dot = sum(a * b for a, b in zip(vec_a, vec_b))
        norm_a = math.sqrt(sum(a * a for a in vec_a))
        norm_b = math.sqrt(sum(b * b for b in vec_b))
        if norm_a == 0.0 or norm_b == 0.0:
            return  # skip zero-norm edge case
        sim = dot / (norm_a * norm_b)
        assert -1.0 <= sim <= 1.0, (
            f"Cosine similarity {sim:.10f} outside [-1, 1]"
        )

    @given(
        st.lists(
            floats(min_value=-1.0, max_value=1.0, allow_nan=False, allow_infinity=False),
            min_size=4, max_size=4
        ),
        st.lists(
            floats(min_value=-1.0, max_value=1.0, allow_nan=False, allow_infinity=False),
            min_size=4, max_size=4
        ),
    )
    def test_similarity_symmetry_property(
        self, vec_a: List[float], vec_b: List[float]
    ):
        """Cosine similarity must be symmetric for any two vectors."""
        assume(sum(v * v for v in vec_a) > 0)  # non-zero norm
        assume(sum(v * v for v in vec_b) > 0)
        dot_ab = sum(a * b for a, b in zip(vec_a, vec_b))
        norm_a = math.sqrt(sum(a * a for a in vec_a))
        norm_b = math.sqrt(sum(b * b for b in vec_b))
        sim_ab = dot_ab / (norm_a * norm_b)
        sim_ba = dot_ab / (norm_b * norm_a)  # same dot product
        assert abs(sim_ab - sim_ba) < 1e-12, (
            f"Similarity not symmetric: {sim_ab:.15f} vs {sim_ba:.15f}"
        )


