class TestStressSimilarity:
    """Stress test similarity computations with many comparisons."""

    def test_all_pairwise_similarities(
        self, index_data: Dict[str, List[float]]
    ):
        """Compute all pairwise similarities to ensure no crashes."""
        doc_ids = list(index_data.keys())
        n_docs = len(doc_ids)
        if n_docs > 50:
            pytest.skip("Too many documents for pairwise test (>50)")
        if n_docs < 2:
            pytest.skip("Need at least 2 documents")
        similarities = []
        for i in range(n_docs):
            for j in range(i + 1, n_docs):
                a = index_data[doc_ids[i]]
                b = index_data[doc_ids[j]]
                dot = sum(va * vb for va, vb in zip(a, b))
                norm_a = math.sqrt(sum(va * va for va in a))
                norm_b = math.sqrt(sum(vb * vb for vb in b))
                if norm_a > 0 and norm_b > 0:
                    sim = dot / (norm_a * norm_b)
                    similarities.append(sim)
        assert len(similarities) == n_docs * (n_docs - 1) // 2, (
            f"Expected {n_docs * (n_docs - 1) // 2} similarities, "
            f"got {len(similarities)}"
        )
        # Verify all similarities are in range
        for sim in similarities:
            assert -1.0 <= sim <= 1.0, (
                f"Similarity {sim:.10f} outside [-1, 1]"
            )

    def test_bulk_normalization(
        self, embedding_matrix: np.ndarray
    ):
        """Compute norms for all embeddings using numpy for speed."""
        if embedding_matrix.size == 0:
            pytest.skip("Empty embedding matrix")
        norms = np.linalg.norm(embedding_matrix, axis=1)
        assert np.all(np.isfinite(norms)), "Non-finite norms detected"
        assert np.all(norms > 0), "Zero-norm embeddings detected"
        # Check norms are within reasonable range
        assert np.all(norms < 100.0), (
            f"Max norm {np.max(norms):.4f} exceeds 100"
        )


