class TestEdgeCases:
    """Test edge cases and malformed data scenarios."""

    def test_empty_index_handling(self):
        """An empty index should be handled gracefully."""
        empty_index: Dict[str, List[float]] = {}
        assert len(empty_index) == 0

    def test_single_document_index(
        self, index_data: Dict[str, List[float]]
    ):
        """A single-document index should still work."""
        if len(index_data) != 1:
            pytest.skip("Index does not have exactly one document")
        doc_id = next(iter(index_data))
        embedding = index_data[doc_id]
        # Self-similarity must be 1.0
        dot = sum(v * v for v in embedding)
        norm = math.sqrt(dot)
        sim = dot / (norm * norm) if norm > 0 else 0.0
        assert abs(sim - 1.0) < 1e-6

    def test_zero_vector_handling(self):
        """Zero vectors should not cause division by zero errors."""
        zero_vec = [0.0, 0.0, 0.0]
        nonzero_vec = [1.0, 2.0, 3.0]
        dot = sum(a * b for a, b in zip(zero_vec, nonzero_vec))
        norm_a = math.sqrt(sum(v * v for v in zero_vec))
        norm_b = math.sqrt(sum(v * v for v in nonzero_vec))
        if norm_a == 0.0 or norm_b == 0.0:
            sim = 0.0
        else:
            sim = dot / (norm_a * norm_b)
        assert sim == 0.0, (
            f"Similarity with zero vector should be 0, got {sim}"
        )

    def test_negative_values_in_embeddings(
        self, index_data: Dict[str, List[float]]
    ):
        """Negative values in embeddings are valid and should not cause issues."""
        has_negative = any(
            any(v < 0 for v in emb) for emb in index_data.values()
        )
        # This is a check, not an assertion; negative values are valid
        if has_negative:
            # Verify similarity still works with negative values
            doc_ids = list(index_data.keys())
            if len(doc_ids) >= 2:
                a = index_data[doc_ids[0]]
                b = index_data[doc_ids[1]]
                dot = sum(va * vb for va, vb in zip(a, b))
                norm_a = math.sqrt(sum(va * va for va in a))
                norm_b = math.sqrt(sum(vb * vb for vb in b))
                if norm_a > 0 and norm_b > 0:
                    sim = dot / (norm_a * norm_b)
                    assert -1.0 <= sim <= 1.0


