class TestPerformance:
    """Benchmark similarity computations for performance regression."""

    @pytest.mark.benchmark
    def test_similarity_computation_speed(
        self, index_data: Dict[str, List[float]], benchmark
    ):
        """Benchmark cosine similarity computation."""
        doc_ids = list(index_data.keys())
        if len(doc_ids) < 2:
            pytest.skip("Need at least 2 documents")
        a = index_data[doc_ids[0]]
        b = index_data[doc_ids[1]]

        def compute_similarity():
            dot = sum(va * vb for va, vb in zip(a, b))
            norm_a = math.sqrt(sum(va * va for va in a))
            norm_b = math.sqrt(sum(vb * vb for vb in b))
            if norm_a > 0 and norm_b > 0:
                return dot / (norm_a * norm_b)
            return 0.0

        result = benchmark(compute_similarity)
        assert -1.0 <= result <= 1.0

    @pytest.mark.benchmark
    def test_full_index_similarity_matrix(
        self, embedding_matrix: np.ndarray, benchmark
    ):
        """Benchmark full similarity matrix computation using numpy."""
        if embedding_matrix.size == 0 or embedding_matrix.shape[0] < 2:
            pytest.skip("Need at least 2 embeddings")
        if embedding_matrix.shape[0] > 100:
            pytest.skip("Too many embeddings for benchmark (>100)")

        def compute_similarity_matrix():
            norms = np.linalg.norm(embedding_matrix, axis=1, keepdims=True)
            normalized = embedding_matrix / norms
            sim_matrix = np.dot(normalized, normalized.T)
            return sim_matrix

        result = benchmark(compute_similarity_matrix)
        # Verify diagonal is all 1s
        assert np.allclose(np.diag(result), 1.0, atol=1e-6)


